// MARK: - Schema: DashboardGithub

/// GitHub contribution-graph aggregate consumed by the GitHub dashboard widget. This is a
/// DS-owned shape with no LP equivalent — it is computed from the GitHub API by the DS
/// pipeline rather than exported by LP.
// MARK: - DashboardGithub
struct DashboardGithub: Codable {
    /// 24-element array of commit counts indexed by hour of day (0 = midnight, 23 = 11 pm). Used
    /// to render the commit-hours histogram.
    let commitHours: [Int]?
    /// 52-week contribution grid as an array of weekly buckets, each containing 7 daily
    /// contribution counts (Sun–Sat). Used to render the GitHub-style heatmap calendar.
    let contributions: [[Int]]
    /// Breakdown of total contributions by type.
    let contributionTypes: ContributionTypes
    /// Recent developer activity feed — commits, PRs, and other events ordered newest-first.
    let devActivity: [DevActivity]?
    /// Map of programming language names to total bytes of code written across all repos.
    let languages: [String: Int]?
    /// High-level summary statistics displayed in the widget header.
    let stats: Stats?
    /// Current and longest consecutive-day contribution streaks.
    let streak: Streak
    /// Short list of the most-starred repositories for display in the repos panel.
    let topRepos: [TopRepo]?
    /// Total contribution count across the entire grid period.
    let totalContributions: Int
    /// Commit counts for each of the past N weeks, ordered oldest-first.
    let weeklyCommits: [Int]?
}

