            rating: rating ?? self.rating,
            status: status ?? self.status,
            title: title ?? self.title
        )
    }

    func jsonData() throws -> Data {
        return try newJSONEncoder().encode(self)
    }

    func jsonString(encoding: String.Encoding = .utf8) throws -> String? {
        return String(data: try self.jsonData(), encoding: encoding)
    }
}

/// Reading status key. Must match a key in statusLabels.
enum Status: String, Codable {
    case completed = "completed"
    case inProgress = "in_progress"
    case next = "next"
}

/// Aggregate reading statistics computed by the DS pipeline.
// MARK: - Stats
struct Stats: Codable {
    /// Average star rating across all rated books.
    let avgRating: Double
    /// Total books started or completed in the current calendar year.
    let booksThisYear: Int
    /// Number of books currently in-progress.
    let currentlyReading: Int
    /// Total number of books with completed status.
    let totalRead: Int
    /// Number of books queued with next status.
    let upNext: Int
}

// MARK: Stats convenience initializers and mutators

extension Stats {
    init(data: Data) throws {
        self = try newJSONDecoder().decode(Stats.self, from: data)
    }

    init(_ json: String, using encoding: String.Encoding = .utf8) throws {
        guard let data = json.data(using: encoding) else {
            throw NSError(domain: "JSONDecoding", code: 0, userInfo: nil)
        }
        try self.init(data: data)
    }

    init(fromURL url: URL) throws {
        try self.init(data: try Data(contentsOf: url))
    }

    func with(
        avgRating: Double? = nil,
        booksThisYear: Int? = nil,
        currentlyReading: Int? = nil,
        totalRead: Int? = nil,
        upNext: Int? = nil
    ) -> Stats {
        return Stats(
            avgRating: avgRating ?? self.avgRating,
            booksThisYear: booksThisYear ?? self.booksThisYear,
            currentlyReading: currentlyReading ?? self.currentlyReading,
            totalRead: totalRead ?? self.totalRead,
            upNext: upNext ?? self.upNext
        )
    }

    func jsonData() throws -> Data {
        return try newJSONEncoder().encode(self)
    }

    func jsonString(encoding: String.Encoding = .utf8) throws -> String? {
        return String(data: try self.jsonData(), encoding: encoding)
    }
}

/// Human-readable display labels keyed by status value. Maps status enum values to UI
/// strings.
// MARK: - StatusLabels
struct StatusLabels: Codable {
    /// Label for recently finished books.
    let completed: String
    /// Label for the book currently being read.
    let inProgress: String
    /// Label for books queued to read next.
    let next: String

    enum CodingKeys: String, CodingKey {
        case completed
        case inProgress = "in_progress"
        case next
    }
}

// MARK: StatusLabels convenience initializers and mutators

extension StatusLabels {
    init(data: Data) throws {
        self = try newJSONDecoder().decode(StatusLabels.self, from: data)
    }

    init(_ json: String, using encoding: String.Encoding = .utf8) throws {
        guard let data = json.data(using: encoding) else {
            throw NSError(domain: "JSONDecoding", code: 0, userInfo: nil)
        }
        try self.init(data: data)
    }

    init(fromURL url: URL) throws {
        try self.init(data: try Data(contentsOf: url))
    }

    func with(
        completed: String? = nil,
        inProgress: String? = nil,
        next: String? = nil
    ) -> StatusLabels {
        return StatusLabels(
            completed: completed ?? self.completed,
            inProgress: inProgress ?? self.inProgress,
            next: next ?? self.next
        )
    }

    func jsonData() throws -> Data {
        return try newJSONEncoder().encode(self)
    }

    func jsonString(encoding: String.Encoding = .utf8) throws -> String? {
        return String(data: try self.jsonData(), encoding: encoding)
    }
}

// MARK: - Helper functions for creating encoders and decoders

// MARK: - Shared Helpers

func newJSONDecoder() -> JSONDecoder {
    let decoder = JSONDecoder()
    if #available(iOS 10.0, OSX 10.12, tvOS 10.0, watchOS 3.0, *) {
        decoder.dateDecodingStrategy = .iso8601
    }
    return decoder
}

func newJSONEncoder() -> JSONEncoder {
    let encoder = JSONEncoder()
    if #available(iOS 10.0, OSX 10.12, tvOS 10.0, watchOS 3.0, *) {
        encoder.dateEncodingStrategy = .iso8601
    }
    return encoder
}

